// === Tab: mySketch ===
let num = 400;

let pos = [];
let vel = [];
let acl = [];
let aclMult = 0.001;

let univR = -1;
let univRMult = 0.01;
let univRChange = -0.01;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	colorMode(HSB);
	noFill();

	reset();
}

function draw() {
	translate(width / 2, height / 2);
	updateObjects();
}

function updateObjects() {
	stroke(frameCount * 0.3 % 255, 255, 255);
	for (let i = 0; i < num; i++) {
		let r = random(TWO_PI);
		acl[i].x += cos(r) * aclMult;
		acl[i].y += sin(r) * aclMult;

		vel[i].x += cos(univR) * univRMult;
		vel[i].y += sin(univR) * univRMult;

		vel[i].add(acl[i]);
		pos[i].add(vel[i]);

		line(pos[i].x, pos[i].y, pos[i].x - vel[i].x * 2, pos[i].y - vel[i].y * 2);
	}

	univR += univRChange;
}

function reset() {
	for (let i = 0; i < num; i++) {
		pos[i] = createVector(0, 0);
		vel[i] = createVector(0, 0);
		acl[i] = createVector(0, 0);
	}
}

function mousePressed() {
	reset();
}

